CREATE FUNCTION public.finalize_store_unification(p_ids uuid[], p_target uuid) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.store_order_installments%ROWTYPE; received integer; paid_day timestamptz; BEGIN FOR p IN SELECT * FROM public.store_order_installments WHERE id=ANY(p_ids) LOOP IF p.paid_at IS NOT NULL THEN received:=CASE WHEN p.paid_amount_cents=0 THEN p.amount_cents ELSE p.paid_amount_cents END; paid_day:=p.paid_at; ELSE SELECT coalesce(sum(a.amount_cents),0),max(a.created_at) INTO received,paid_day FROM public.store_installment_advances a WHERE a.installment_id=p.id; END IF; IF received>0 THEN UPDATE public.store_order_installments SET amount_cents=received,paid_at=coalesce(paid_day,now()) WHERE id=p.id; ELSE UPDATE public.store_order_installments SET merged_into_order_id=p_target WHERE id=p.id; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.finalize_store_unification(uuid[],uuid) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.create_unified_store_order(uuid,uuid,jsonb,jsonb,integer,integer,date,text,text,text)'::regprocedure) INTO definition; IF position('UPDATE public.store_order_installments SET merged_into_order_id=p_order_id WHERE id=ANY(source_ids);' in definition)=0 THEN RAISE EXCEPTION 'Expected unification statement missing'; END IF; definition:=replace(definition,'UPDATE public.store_order_installments SET merged_into_order_id=p_order_id WHERE id=ANY(source_ids);','PERFORM public.finalize_store_unification(source_ids,p_order_id);'); EXECUTE definition; END $$;